import { loadFont as loadMont } from "@remotion/google-fonts/Montserrat";
import { loadFont as loadCorm } from "@remotion/google-fonts/CormorantGaramond";
import React from "react";
import { AbsoluteFill, Audio, Easing, Img, OffthreadVideo, Sequence, interpolate, staticFile, useCurrentFrame } from "remotion";

// Odson cosméticos (Othon Santana) · VSL v2 na horizontal (1920×1080), pedido do cliente em 22/10: "esse mesmo vídeo na
// horizontal". Mesma voz, mesmo som (mix-v2.wav), mesmos tempos e cenas da OdsonV2 vertical; cada cena foi recomposta em
// duas colunas (texto de um lado, produto ou gráfico do outro), alternando o lado, em vez de esticar o quadro vertical.
// - Todo texto passa pelo Fit: mede a largura na fonte real e reduz o corpo até caber na coluna (margem de 120 px).
// - Nada que fica perto da margem cresce além de 1 (sem câmera que aproxima a cena inteira).
// - Trocas em "chicote": a cena que sai e a que entra andam juntas, com desfoque de movimento; cada troca de um jeito.
// - Cenas curtas (2 a 4 s), produto real (vídeos do cliente) em 5 momentos, gente real no gancho e na chamada.
// Identidade: azul-marinho e dourado do símbolo; Montserrat pesada (OTHON) e Cormorant itálico (SANTANA).
// Tempos = tempo da palavra na voz v2; `t` já desconta a entrada da locução.

const { fontFamily: M } = loadMont("normal", { weights: ["600", "700", "800", "900"], subsets: ["latin", "latin-ext"] });
const { fontFamily: C } = loadCorm("italic", { weights: ["600"], subsets: ["latin", "latin-ext"] });

export const OD2W_FPS = 30;
const LEAD = 0.15;
export const OD2W_FRAMES = Math.round(57.3 * OD2W_FPS);
const fr = (s: number) => Math.max(0, Math.round((s + LEAD) * OD2W_FPS));

const cl = { extrapolateLeft: "clamp", extrapolateRight: "clamp" } as const;
const OUT = Easing.bezier(0.16, 1, 0.3, 1);
const BACK = Easing.out(Easing.back(1.6));
const INOUT = Easing.bezier(0.7, 0, 0.3, 1);
const k = (t: number, a: number, d = 0.4) => interpolate(t, [a, a + d], [0, 1], { ...cl, easing: OUT });
const pop = (t: number, a: number, d = 0.42) => interpolate(t, [a, a + d], [0, 1], { ...cl, easing: BACK });
const lin = (t: number, a: number, b: number) => interpolate(t, [a, b], [0, 1], cl);

const NAVY = "#0A1830";
const NAVY2 = "#132B52";
const BLUE = "#1E5FB4";
const IVORY = "#F7F2E8";
const WHITE = "#FFFFFF";
const GOLD = "linear-gradient(100deg, #F6DE9A 0%, #E2B55A 38%, #B7832C 70%, #F0CF7E 100%)";
const GOLD_S = "#D9A848";
const SHADOW_D = "0 40px 90px rgba(0,0,0,0.45), 0 6px 18px rgba(0,0,0,0.25)";
const SHADOW_L = "0 30px 70px rgba(10,24,48,0.16), 0 4px 14px rgba(10,24,48,0.08)";
const MAXW = 740;
const W = 1920, H = 1080;
const LX = 510, RX = 1410;        // centro da coluna da esquerda e da direita

// ───────── texto que sempre cabe ─────────
let ctx: CanvasRenderingContext2D | null = null;
const widthOf = (text: string, font: string) => {
  if (!ctx) ctx = document.createElement("canvas").getContext("2d");
  if (!ctx) return 0;
  ctx.font = font;
  return ctx.measureText(text).width;
};
const fit = (text: string, size: number, weight: number, serif = false, max = MAXW) => {
  const w = widthOf(text, `${serif ? "italic " : ""}${serif ? 600 : weight} ${size}px ${serif ? C : M}`);
  return w > max ? Math.floor((size * max) / (w * 1.04)) : size;
};
const gold = (): React.CSSProperties => ({ backgroundImage: GOLD, WebkitBackgroundClip: "text", backgroundClip: "text", color: "transparent" });
const blurIn = (t: number, at: number, d = 0.35): React.CSSProperties => {
  const e = k(t, at, d);
  return { opacity: Math.min(1, e * 1.7), filter: `blur(${((1 - e) * 14).toFixed(1)}px)`, transform: `translateY(${((1 - e) * 40).toFixed(1)}px) scale(${(0.9 + 0.1 * e).toFixed(4)})` };
};
// uma linha: entra (desfoque + subida curta) e fica parada
const Tx: React.FC<{ t: number; at: number; text: string; size: number; weight?: number; serif?: boolean; hl?: boolean; color?: string; max?: number }> = ({ t, at, text, size, weight = 800, serif, hl, color = WHITE, max }) => {
  const s = fit(text, size, weight, serif, max);
  return (
    <div style={{ fontFamily: serif ? C : M, fontStyle: serif ? "italic" : "normal", fontWeight: serif ? 600 : weight, fontSize: s, lineHeight: 1.12, letterSpacing: serif ? "0" : "-0.02em", whiteSpace: "nowrap", color, paddingBottom: s * 0.06, textAlign: "center", ...(hl ? gold() : {}), ...blurIn(t, at) }}>
      {text}
    </div>
  );
};
// bloco de linhas centralizado numa altura
const Block: React.FC<{ top: number; gap?: number; cx?: number; w?: number; children: React.ReactNode }> = ({ top, gap = 0, cx = W / 2, w = 760, children }) => (
  <div style={{ position: "absolute", left: cx - w / 2, width: w, top, display: "flex", flexDirection: "column", alignItems: "center", gap }}>{children}</div>
);
// coluna centrada verticalmente
const Col: React.FC<{ cx: number; w?: number; gap?: number; children: React.ReactNode }> = ({ cx, w = 760, gap = 0, children }) => (
  <div style={{ position: "absolute", left: cx - w / 2, width: w, top: 0, height: H, display: "flex", flexDirection: "column", alignItems: "center", justifyContent: "center", gap }}>{children}</div>
);

// ───────── vídeo recortado num cartão ─────────
type Cut = { src: string; from: number; to: number; start: number; crop: [number, number, number]; zoom: [number, number] };
const SW = 476, SH = 848;
const Clips: React.FC<{ t: number; cuts: Cut[]; w: number; h: number; r?: number; border?: boolean }> = ({ t, cuts, w, h, r = 40, border = true }) => (
  <div style={{ position: "relative", width: w, height: h, borderRadius: r, overflow: "hidden", background: NAVY2, boxShadow: SHADOW_D }}>
    {cuts.map((c, i) => {
      const s = w / c.crop[2];
      const z = interpolate(t, [c.from, c.to], c.zoom, cl);
      return (
        <Sequence key={i} from={fr(c.from)} durationInFrames={Math.max(1, fr(c.to) - fr(c.from))} layout="none">
          <div style={{ position: "absolute", inset: 0, transform: `scale(${z.toFixed(4)})` }}>
            <OffthreadVideo muted src={staticFile(`odson/${c.src}`)} trimBefore={Math.round(c.start * OD2W_FPS)} style={{ position: "absolute", width: SW * s, height: SH * s, left: -c.crop[0] * s, top: -c.crop[1] * s, maxWidth: "none" }} />
          </div>
        </Sequence>
      );
    })}
    {border ? <div style={{ position: "absolute", inset: 0, borderRadius: r, border: `3px solid ${GOLD_S}`, boxSizing: "border-box" }} /> : null}
  </div>
);
const V1 = "video-1.mp4", V2 = "video-2.mp4";
const V1CROP: [number, number, number] = [52, 132, 374];      // só a metade de cima (perfume da Amei); a de baixo é marca de terceiro
const punch = (t: number, ats: number[], amt = 0.035) => 1 + amt * ats.reduce((m, a) => Math.max(m, t >= a ? 1 - k(t, a, 0.3) : 0), 0);
const bob = (t: number, ph = 0, amp = 8) => Math.sin(t * 2.1 + ph) * amp;

// ───────── ícones ─────────
const Ico: React.FC<{ d: string[]; s: number; c: string; w?: number }> = ({ d, s, c, w = 2.2 }) => (
  <svg width={s} height={s} viewBox="0 0 24 24" fill="none" stroke={c} strokeWidth={w} strokeLinecap="round" strokeLinejoin="round">{d.map((p, i) => <path key={i} d={p} />)}</svg>
);
const I = {
  user: ["M16 21v-2a4 4 0 0 0-4-4H6a4 4 0 0 0-4 4v2", "M9 11a4 4 0 1 0 0-8 4 4 0 0 0 0 8z", "M19 8v6", "M22 11h-6"],
  box: ["M21 8l-9-5-9 5 9 5 9-5z", "M3 8v8l9 5 9-5V8", "M12 13v8"],
  tag: ["M20.6 13.4l-7.2 7.2a2 2 0 0 1-2.8 0L2 12V2h10l8.6 8.6a2 2 0 0 1 0 2.8z", "M7 7h.01"],
  coin: ["M12 2v20", "M17 5H9.5a3.5 3.5 0 0 0 0 7h5a3.5 3.5 0 0 1 0 7H6"],
  person: ["M20 21v-2a4 4 0 0 0-4-4H8a4 4 0 0 0-4 4v2", "M12 11a4 4 0 1 0 0-8 4 4 0 0 0 0 8z"],
  gift: ["M20 12v10H4V12", "M2 7h20v5H2z", "M12 22V7", "M12 7H7.5a2.5 2.5 0 0 1 0-5C11 2 12 7 12 7z", "M12 7h4.5a2.5 2.5 0 0 0 0-5C13 2 12 7 12 7z"],
  cap: ["M22 10L12 5 2 10l10 5 10-5z", "M6 12v5c3 3 9 3 12 0v-5", "M22 10v6"],
  headset: ["M3 18v-6a9 9 0 0 1 18 0v6", "M21 19a2 2 0 0 1-2 2h-1a2 2 0 0 1-2-2v-3a2 2 0 0 1 2-2h3z", "M3 19a2 2 0 0 0 2 2h1a2 2 0 0 0 2-2v-3a2 2 0 0 0-2-2H3z"],
  book: ["M4 19.5A2.5 2.5 0 0 1 6.5 17H20", "M6.5 2H20v20H6.5A2.5 2.5 0 0 1 4 19.5v-15A2.5 2.5 0 0 1 6.5 2z"],
  star: ["M12 2l3.1 6.3 6.9 1-5 4.9 1.2 6.8L12 17.8 5.8 21l1.2-6.8-5-4.9 6.9-1z"],
