};
const WaIcon: React.FC<{ s: number }> = ({ s }) => (
  <svg width={s} height={s} viewBox="0 0 24 24" fill={WHITE}>
    <path d="M12 2a10 10 0 0 0-8.6 15.1L2 22l5-1.3A10 10 0 1 0 12 2zm0 18.2a8.2 8.2 0 0 1-4.2-1.2l-.3-.2-3 .8.8-2.9-.2-.3A8.2 8.2 0 1 1 12 20.2zm4.5-6.1c-.2-.1-1.5-.7-1.7-.8-.2-.1-.4-.1-.6.1l-.8 1c-.1.2-.3.2-.5.1a6.7 6.7 0 0 1-3.300-2.9c-.3-.4.3-.4.7-1.300.1-.2 0-.3 0-.4l-.8-1.800c-.2-.5-.4-.4-.6-.4h-.5a1 1 0 0 0-.7.3 3 3 0 0 0-.9 2.200 5.200 5.200 0 0 0 1.100 2.700 11.800 11.800 0 0 0 4.500 4c1.700.7 2.300.8 3.200.6.5-.1 1.500-.6 1.700-1.200.2-.6.2-1.100.2-1.200-.1-.1-.3-.2-.5-.3z" />
  </svg>
);
const Badge: React.FC<{ s: number; ico: string[]; on?: boolean }> = ({ s, ico, on }) => (
  <div style={{ width: s, height: s, borderRadius: s / 2, background: on ? undefined : NAVY, backgroundImage: on ? GOLD : undefined, display: "flex", alignItems: "center", justifyContent: "center", flexShrink: 0, boxShadow: on ? "0 0 40px rgba(226,181,90,0.45)" : `inset 0 0 0 3px ${GOLD_S}` }}>
    <Ico d={ico} s={s * 0.5} c={on ? NAVY : GOLD_S} />
  </div>
);
// linha de cartão: ícone + rótulo
const Row: React.FC<{ t: number; at: number; ico: string[]; label: string; h?: number; w?: number; light?: boolean; on?: boolean; from?: number; thumb?: React.ReactNode }> = ({ t, at, ico, label, h = 150, w = 760, light, on, from = 1, thumb }) => {
  const e = pop(t, at, 0.5);
  const lines = label.split("\n");
  const s = Math.min(...lines.map((l) => fit(l, 64, 800, false, w - (thumb ? h + 40 : h) - 110)));
  return (
    <div style={{ width: w, height: h, borderRadius: 36, background: light ? WHITE : on ? NAVY2 : "rgba(255,255,255,0.05)", border: light ? "none" : `3px solid ${on ? GOLD_S : "rgba(217,168,72,0.3)"}`, boxShadow: light ? SHADOW_L : on ? "0 20px 50px rgba(0,0,0,0.35)" : "none", boxSizing: "border-box", display: "flex", alignItems: "center", gap: 36, padding: "0 34px 0 20px", opacity: Math.min(1, e * 2), transform: `translateX(${((1 - e) * 280 * from).toFixed(1)}px)` }}>
      {thumb ?? <Badge s={h - 44} ico={ico} on={on} />}
      <div style={{ fontFamily: M, fontWeight: 800, fontSize: s, lineHeight: 1.05, letterSpacing: "-0.02em", color: light ? NAVY : WHITE, whiteSpace: "pre" }}>{label}</div>
    </div>
  );
};

// ═════════ cenas (horizontal) ═════════
