// ═════════ roteiro de cenas e trocas (as mesmas da vertical) ═════════
type Tr = "up" | "left" | "zoom" | "right" | "circle" | "down" | "split" | "zoomOut" | "fade";
type Sc = { a: number; el: React.FC<{ t: number }>; tr: Tr };
const SCENES: Sc[] = [
  { a: -1, el: Gancho, tr: "fade" },
  { a: 4.45, el: Atencao, tr: "circle" },
  { a: 6.15, el: Imagine, tr: "up" },
  { a: 9.35, el: Desconto, tr: "zoom" },
  { a: 11.35, el: Revender, tr: "left" },
  { a: 13.4, el: Etapas, tr: "up" },
  { a: 20.6, el: Ciclo, tr: "zoomOut" },
  { a: 24.3, el: Exemplo, tr: "right" },
  { a: 33.85, el: Procura, tr: "split" },
  { a: 38.2, el: Anos, tr: "down" },
  { a: 42.3, el: Inspirados, tr: "zoom" },
  { a: 45.85, el: Suporte, tr: "circle" },
  { a: 48.3, el: Chamada, tr: "up" },
  { a: 55.35, el: Fecho, tr: "fade" },
];
const HALF = 0.22;
const enter = (tr: Tr, p: number): React.CSSProperties => {
  const mb = Math.sin(Math.PI * p) * 26;
  switch (tr) {
    case "up": return { transform: `translateY(${((1 - p) * H).toFixed(1)}px)`, filter: `blur(${mb.toFixed(1)}px)` };
    case "down": return { transform: `translateY(${((p - 1) * H).toFixed(1)}px)`, filter: `blur(${mb.toFixed(1)}px)` };
    case "left": return { transform: `translateX(${((1 - p) * W).toFixed(1)}px)`, filter: `blur(${mb.toFixed(1)}px)` };
    case "right": return { transform: `translateX(${((p - 1) * W).toFixed(1)}px)`, filter: `blur(${mb.toFixed(1)}px)` };
    case "zoom": return { transform: `scale(${(0.55 + 0.45 * p).toFixed(4)})`, opacity: p, filter: `blur(${mb.toFixed(1)}px)` };
    case "zoomOut": return { transform: `scale(${(1.5 - 0.5 * p).toFixed(4)})`, opacity: p, filter: `blur(${mb.toFixed(1)}px)` };
    case "circle": return { clipPath: `circle(${(p * 2300).toFixed(0)}px at ${W / 2}px ${H / 2}px)` };
    case "split": return { clipPath: `inset(${((1 - p) * 50).toFixed(2)}% 0 ${((1 - p) * 50).toFixed(2)}% 0)` };
    default: return { opacity: p };
  }
};
const leave = (tr: Tr, p: number): React.CSSProperties => {
  const mb = Math.sin(Math.PI * p) * 26;
  switch (tr) {
    case "up": return { transform: `translateY(${(-p * H).toFixed(1)}px)`, filter: `blur(${mb.toFixed(1)}px)` };
    case "down": return { transform: `translateY(${(p * H).toFixed(1)}px)`, filter: `blur(${mb.toFixed(1)}px)` };
    case "left": return { transform: `translateX(${(-p * W).toFixed(1)}px)`, filter: `blur(${mb.toFixed(1)}px)` };
    case "right": return { transform: `translateX(${(p * W).toFixed(1)}px)`, filter: `blur(${mb.toFixed(1)}px)` };
    case "zoom": return { transform: `scale(${(1 + 0.5 * p).toFixed(4)})`, opacity: 1 - p };
    case "zoomOut": return { transform: `scale(${(1 - 0.3 * p).toFixed(4)})`, opacity: 1 - p };
    case "circle": case "split": return { transform: `scale(${(1 - 0.08 * p).toFixed(4)})`, filter: `brightness(${(1 - 0.4 * p).toFixed(3)})` };
    default: return {};
  }
};

export const OdsonV2Wide: React.FC = () => {
  const t = useCurrentFrame() / OD2W_FPS - LEAD;
  return (
    <AbsoluteFill style={{ background: NAVY }}>
      <Audio src={staticFile("odson/mix-v2.wav")} />
      {SCENES.map((s, i) => {
        const next = SCENES[i + 1];
        const a = s.a, b = next ? next.a : 99;
        if (t < a - HALF || t >= b + HALF) return null;
        const pin = i === 0 ? 1 : interpolate(t, [a - HALF, a + HALF], [0, 1], { ...cl, easing: INOUT });
        const pout = next ? interpolate(t, [b - HALF, b + HALF], [0, 1], { ...cl, easing: INOUT }) : 0;
        const st: React.CSSProperties = t < a + HALF && i > 0 ? enter(s.tr, pin) : pout > 0 ? leave(next!.tr, pout) : {};
        const El = s.el;
        return (
          <AbsoluteFill key={i} style={{ ...st, zIndex: i }}>
            <El t={t} />
          </AbsoluteFill>
        );
      })}
    </AbsoluteFill>
  );
};

